import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api';
import { Box, Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Button, Select, MenuItem, InputLabel, FormControl } from '@mui/material';

const ExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState('');
  const [franchises, setFranchises] = useState([]);
  const [examDataList, setExamDataList] = useState([]);
  const [editingExam, setEditingExam] = useState(null); // State for the exam being edited

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []);

  // Get exams based on selected franchise
  const getFranchiseExams = (franchiseId) => {
    const franchise = franchises.find((f) => f._id === franchiseId);
    return franchise ? franchise.examData : [];
  };

  // Handle filter change for franchise
  const handleFilterChange = (e) => {
    const selectedFranchiseId = e.target.value;
    setFilterFranchiseId(selectedFranchiseId);
    if (selectedFranchiseId) {
      const exams = getFranchiseExams(selectedFranchiseId);
      setExamDataList(exams);
    } else {
      setExamDataList([]);
    }
  };

  // Handle delete exam
  const handleDeleteExam = async (examId) => {
    try {
      await deleteExamData(filterFranchiseId, examId); // Passing franchiseId and examId to delete
      setExamDataList(examDataList.filter((exam) => exam._id !== examId));
      alert('Exam deleted successfully');
    } catch (error) {
      console.error('Error deleting exam:', error);
      alert('Failed to delete exam');
    }
  };

  // Handle edit exam (open the edit form)
  const handleEditExam = (exam) => {
    const franchiseId = filterFranchiseId;
    const updatedExam = { ...exam, franchiseId };
    setEditingExam(updatedExam);
  };

  // Handle form input changes for editing
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setEditingExam((prevExam) => ({
      ...prevExam,
      [name]: value,
    }));
  };

  // Handle save exam (update the exam data)
  const handleSaveExam = async (e) => {
    e.preventDefault();

    if (!editingExam.franchiseId || !editingExam._id) {
      return;
    }

    try {
      const updatedExam = await updateExamData(editingExam);
      setExamDataList((prevData) =>
        prevData.map((exam) => (exam._id === updatedExam._id ? updatedExam : exam))
      );
      setEditingExam(null); // Close the edit form
      alert('Exam updated successfully');
    } catch (error) {
      console.error('Error saving exam data:', error);
      alert('Failed to update exam');
    }
  };

  return (
    <Box sx={{ padding: 3 }}>
      <Typography variant="h4" sx={{ fontWeight: 'bold', marginBottom: 3 }}>
        Manage Exam Data
      </Typography>

      {/* Franchise filter dropdown */}
      <FormControl fullWidth sx={{ marginBottom: 3 }}>
        <InputLabel id="filterFranchiseId">Filter by Franchise</InputLabel>
        <Select
          labelId="filterFranchiseId"
          value={filterFranchiseId}
          onChange={handleFilterChange}
          label="Filter by Franchise"
        >
          <MenuItem value="">All</MenuItem>
          {franchises.map((franchise) => (
            <MenuItem key={franchise._id} value={franchise._id}>
              {franchise.name}
            </MenuItem>
          ))}
        </Select>
      </FormControl>

      {/* Render edit form if editing an exam */}
      {editingExam ? (
        <Box sx={{ marginBottom: 3 }}>
          <Typography variant="h5" sx={{ marginBottom: 2 }}>
            Edit Exam
          </Typography>
          <form onSubmit={handleSaveExam}>
            <Box sx={{ marginBottom: 2 }}>
              <Typography>Exam Name:</Typography>
              <input
                type="text"
                name="examName"
                value={editingExam.examName}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginBottom: '8px' }}
              />
            </Box>
            <Box sx={{ marginBottom: 2 }}>
              <Typography>Date:</Typography>
              <input
                type="date"
                name="date"
                value={editingExam.date}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginBottom: '8px' }}
              />
            </Box>
            <Box sx={{ marginBottom: 2 }}>
              <Typography>Students Attended:</Typography>
              <input
                type="number"
                name="studentsAttended"
                value={editingExam.studentsAttended}
                onChange={handleInputChange}
                style={{ width: '100%', padding: '8px', marginBottom: '8px' }}
              />
            </Box>
            <Button type="submit" variant="contained" color="primary" sx={{ marginRight: 2 }}>
              Save Changes
            </Button>
            <Button type="button" variant="outlined" onClick={() => setEditingExam(null)}>
              Cancel
            </Button>
          </form>
        </Box>
      ) : (
        <Typography variant="h6" sx={{ marginBottom: 2 }}>
          Exam Data
        </Typography>
      )}

      {/* Table to display exam data */}
      {examDataList.length > 0 ? (
        <TableContainer sx={{ maxHeight: 500, overflowY: 'auto' }}>
          <Table sx={{ minWidth: 650 }} aria-label="Exam Data">
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 'bold' }}>Exam Name</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Date</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Students Attended</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {examDataList.map((exam) => (
                <TableRow key={exam._id}>
                  <TableCell>{exam.examName}</TableCell>
                  <TableCell>{exam.date}</TableCell>
                  <TableCell>{exam.studentsAttended}</TableCell>
                  <TableCell>
                    <Button
                      variant="outlined"
                      color="primary"
                      sx={{ marginRight: 1 }}
                      onClick={() => handleEditExam(exam)}
                    >
                      Edit
                    </Button>
                    <Button variant="outlined" color="secondary" onClick={() => handleDeleteExam(exam._id)}>
                      Delete
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      ) : (
        <Typography>No exam data available for the selected franchise.</Typography>
      )}
    </Box>
  );
};

export default ExamData;
